    bronze_pouringcrucibletongs = { name = "Bronast klešče za livljenje", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast klešče za livljenje za livarje." },
    silver_pouringcrucibletongs = { name = "Srebrn klešče za livljenje", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn klešče za livljenje za livarje." },
