}
PouringCrucibleTongsMaker.ironStock=18; PouringCrucibleTongsMaker.bronzeStock=14; PouringCrucibleTongsMaker.woodStock=10; PouringCrucibleTongsMaker.leatherStock=8; PouringCrucibleTongsMaker.silverStock=8; PouringCrucibleTongsMaker.goldStock=6; PouringCrucibleTongsMaker.jewelStock=4; PouringCrucibleTongsMaker.pearlStock=4
PouringCrucibleTongsMaker.productStock = {}; PouringCrucibleTongsMaker.buildings = {}; PouringCrucibleTongsMaker.maker = nil; PouringCrucibleTongsMaker.activeMaking = {}; PouringCrucibleTongsMaker.totalProducts = 0; PouringCrucibleTongsMaker.dayTimer = 0
function PouringCrucibleTongsMaker.init() PouringCrucibleTongsMaker.ironStock=18; PouringCrucibleTongsMaker.bronzeStock=14; PouringCrucibleTongsMaker.woodStock=10; PouringCrucibleTongsMaker.leatherStock=8; PouringCrucibleTongsMaker.silverStock=8; PouringCrucibleTongsMaker.goldStock=6; PouringCrucibleTongsMaker.jewelStock=4; PouringCrucibleTongsMaker.pearlStock=4; PouringCrucibleTongsMaker.productStock={}; PouringCrucibleTongsMaker.buildings={}; PouringCrucibleTongsMaker.maker=nil; PouringCrucibleTongsMaker.activeMaking={}; PouringCrucibleTongsMaker.totalProducts=0; PouringCrucibleTongsMaker.dayTimer=0; print("[PouringCrucibleTongsMaker] Royal Pouring Crucible Tongs Maker System initialized (6 products, 4 buildings)") end
function PouringCrucibleTongsMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PouringCrucibleTongsMaker.maker={name=n or ("Kleščar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kleščar najet: %s (spretnost: %d)",PouringCrucibleTongsMaker.maker.name,s),"success") end; return true end
function PouringCrucibleTongsMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PouringCrucibleTongsMaker.build(id) local ok,e=PouringCrucibleTongsMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PouringCrucibleTongsMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PouringCrucibleTongsMaker.getQualityBonus() local b=0; for _,bd in ipairs(PouringCrucibleTongsMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PouringCrucibleTongsMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and PouringCrucibleTongsMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and PouringCrucibleTongsMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and PouringCrucibleTongsMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and PouringCrucibleTongsMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and PouringCrucibleTongsMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PouringCrucibleTongsMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PouringCrucibleTongsMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PouringCrucibleTongsMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PouringCrucibleTongsMaker.buildings==0 then return false,"Potrebna kleščna delavnica" end; if not PouringCrucibleTongsMaker.maker then return false,"Potreben klescar" end; return true end
function PouringCrucibleTongsMaker.make(pt,qty) qty=qty or 1; local ok,e=PouringCrucibleTongsMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then PouringCrucibleTongsMaker.ironStock=PouringCrucibleTongsMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then PouringCrucibleTongsMaker.bronzeStock=PouringCrucibleTongsMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then PouringCrucibleTongsMaker.woodStock=PouringCrucibleTongsMaker.woodStock-d.woodCost*qty end; if d.leatherCost then PouringCrucibleTongsMaker.leatherStock=PouringCrucibleTongsMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then PouringCrucibleTongsMaker.silverStock=PouringCrucibleTongsMaker.silverStock-d.silverCost*qty end; if d.goldCost then PouringCrucibleTongsMaker.goldStock=PouringCrucibleTongsMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PouringCrucibleTongsMaker.jewelStock=PouringCrucibleTongsMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PouringCrucibleTongsMaker.pearlStock=PouringCrucibleTongsMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PouringCrucibleTongsMaker.maker then t=math.max(1,t-math.floor(PouringCrucibleTongsMaker.maker.skill/13)) end; table.insert(PouringCrucibleTongsMaker.activeMaking,{id="pouringcrucibletongs_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PouringCrucibleTongsMaker.completeMaking(m) local q=1.0+(PouringCrucibleTongsMaker.getQualityBonus()/100); if PouringCrucibleTongsMaker.maker then q=q+(PouringCrucibleTongsMaker.maker.skill/140) end; q=math.min(2.5,q); PouringCrucibleTongsMaker.productStock[m.productType]=(PouringCrucibleTongsMaker.productStock[m.productType] or 0)+m.quantity; PouringCrucibleTongsMaker.totalProducts=PouringCrucibleTongsMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PouringCrucibleTongsMaker.maker then PouringCrucibleTongsMaker.maker.itemsMade=PouringCrucibleTongsMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PouringCrucibleTongsMaker.maker.skill=math.min(100,PouringCrucibleTongsMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Klešče izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"pouringcrucibletongs.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function PouringCrucibleTongsMaker.update(dt) if not _G.state then return end; PouringCrucibleTongsMaker.dayTimer=PouringCrucibleTongsMaker.dayTimer+dt; if PouringCrucibleTongsMaker.dayTimer>=30 then PouringCrucibleTongsMaker.dayTimer=0; for i=#PouringCrucibleTongsMaker.activeMaking,1,-1 do local m=PouringCrucibleTongsMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PouringCrucibleTongsMaker.completeMaking(m); table.remove(PouringCrucibleTongsMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PouringCrucibleTongsMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PouringCrucibleTongsMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PouringCrucibleTongsMaker.getStats() return {ironStock=PouringCrucibleTongsMaker.ironStock,bronzeStock=PouringCrucibleTongsMaker.bronzeStock,woodStock=PouringCrucibleTongsMaker.woodStock,leatherStock=PouringCrucibleTongsMaker.leatherStock,silverStock=PouringCrucibleTongsMaker.silverStock,goldStock=PouringCrucibleTongsMaker.goldStock,jewelStock=PouringCrucibleTongsMaker.jewelStock,pearlStock=PouringCrucibleTongsMaker.pearlStock,productStock=PouringCrucibleTongsMaker.productStock,numBuildings=#PouringCrucibleTongsMaker.buildings,hasMaker=PouringCrucibleTongsMaker.maker~=nil,makerName=PouringCrucibleTongsMaker.maker and PouringCrucibleTongsMaker.maker.name or "—",makerSkill=PouringCrucibleTongsMaker.maker and PouringCrucibleTongsMaker.maker.skill or 0,activeMaking=#PouringCrucibleTongsMaker.activeMaking,totalProducts=PouringCrucibleTongsMaker.totalProducts} end
